<?php require_once __DIR__.'/../layouts/header.php'; mostrarFlash(); ?>
<div class="d-flex flex-column flex-lg-row justify-content-between gap-3 mb-4"><div><span class="eyebrow">Tutoría de materias</span><h1 class="page-title mb-1">Tutorías grupales</h1><p class="text-muted mb-0">Sesiones basadas exclusivamente en el horario oficial de la universidad.</p></div><?php if(esAdministrador()): ?><a href="tutorias_grupales_crear.php" class="btn btn-primary"><i class="bi bi-calendar-plus me-1"></i>Programar sesión</a><?php endif;?></div>
<div class="card card-custom p-3 mb-3"><form method="get" class="d-flex gap-2"><select class="form-select" name="estado" style="max-width:250px"><option value="">Todos los estados</option><?php foreach(['programada','en_curso','realizada','cancelada'] as $s): ?><option value="<?=e($s)?>" <?=($estado??'')===$s?'selected':''?>><?=e(ucwords(str_replace('_',' ',$s)))?></option><?php endforeach;?></select><button class="btn btn-outline-primary">Filtrar</button></form></div>
<div class="card card-custom overflow-hidden"><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead class="table-light"><tr><th>Fecha</th><th>Materia</th><th>Tutor</th><th>Horario</th><th>Estudiantes</th><th>Estado</th><th class="text-end">Acciones</th></tr></thead><tbody><?php foreach($registros as $r): ?><tr><td><strong><?=e(date('d/m/Y',strtotime($r['fecha'])))?></strong></td><td><?=e($r['nombre_materia'])?><div class="small text-muted"><?=e($r['nombre_carrera'])?></div></td><td><?=e(trim($r['tutor_nombre'].' '.$r['tutor_apellido']))?></td><td><?=e($r['dia_semana'])?><div class="small text-muted"><?=e(substr($r['hora_inicio'],0,5))?>–<?=e(substr($r['hora_fin'],0,5))?> · <?=e(ucfirst($r['turno']))?></div></td><td><span class="badge text-bg-light border"><i class="bi bi-people me-1"></i><?=e($r['total_estudiantes'])?></span></td><td><span class="badge text-bg-<?=match($r['estado']){'programada'=>'primary','en_curso'=>'warning','realizada'=>'success','cancelada'=>'danger',default=>'secondary'}?>"><?=e(ucwords(str_replace('_',' ',$r['estado'])))?></span></td><td class="text-end"><div class="d-flex justify-content-end gap-1"><?php if(esEstudiante()): $inscrito=$inscripciones[(int)$r['id_tutoria_grupal']]??false; ?><form method="post" action="tutorias_grupales_estudiante_accion.php"><?=csrfField()?><input type="hidden" name="id_tutoria_grupal" value="<?=e($r['id_tutoria_grupal'])?>"><button name="accion" value="<?=$inscrito?'retirarse':'inscribirse'?>" class="btn btn-sm btn-outline-<?=$inscrito?'danger':'primary'?>"><?=$inscrito?'Retirarme':'Inscribirme'?></button></form><?php else: ?><a href="tutorias_grupales_estudiantes.php?id=<?=e($r['id_tutoria_grupal'])?>" class="btn btn-sm btn-outline-secondary" title="Ver estudiantes"><i class="bi bi-people"></i><span class="d-none d-xl-inline ms-1">Estudiantes</span></a><?php if(esTutor() && $r['estado']==='programada'): ?><form method="post" action="tutorias_grupales_accion.php"><?=csrfField()?><input type="hidden" name="id_tutoria_grupal" value="<?=e($r['id_tutoria_grupal'])?>"><button name="accion" value="iniciar" class="btn btn-sm btn-outline-primary">Iniciar</button></form><?php endif;?><?php if(esTutor() && $r['estado']==='en_curso'): ?><form method="post" action="tutorias_grupales_accion.php"><?=csrfField()?><input type="hidden" name="id_tutoria_grupal" value="<?=e($r['id_tutoria_grupal'])?>"><button name="accion" value="realizar" class="btn btn-sm btn-outline-success">Finalizar</button></form><?php endif;?><?php if((esTutor()||esAdministrador()) && in_array($r['estado'],['programada','en_curso'],true)): ?><form method="post" action="tutorias_grupales_accion.php" onsubmit="return confirm('¿Cancelar esta sesión grupal?');"><?=csrfField()?><input type="hidden" name="id_tutoria_grupal" value="<?=e($r['id_tutoria_grupal'])?>"><button name="accion" value="cancelar" class="btn btn-sm btn-outline-danger">Cancelar</button></form><?php endif;?><?php endif;?></div></td></tr><?php endforeach;?><?php if(!$registros): ?><tr><td colspan="7" class="text-center py-5 text-muted"><i class="bi bi-calendar-x fs-1 d-block mb-2"></i>No hay sesiones grupales para mostrar.</td></tr><?php endif;?></tbody></table></div></div>
